changes:
/* Isolate website controls from the enquiry queue's generic button/hover rules. */
#root .track-site-shell .ws-page button{margin:0;font-weight:500;background:#fff;color:#293241;border:1px solid #d1d8e0;border-radius:9px;transform:none}
#root .track-site-shell .ws-page button:hover:not(:disabled){background:#eef3fb;color:#254b9c;border-color:#a3b8d7;transform:none}
#root .track-site-shell .ws-tabs button{background:transparent;border:0;border-bottom:2px solid transparent;border-radius:0;color:#596371;padding:9px 15px}
#root .track-site-shell .ws-tabs button[aria-selected=true]{background:#eaf0fb;color:#254b9c;border-bottom-color:#335cbd;font-weight:600}
#root .track-site-shell .ws-pages-list button{padding:0;background:transparent;color:#31425a;border:0;border-radius:0;text-align:left;justify-content:flex-start}
#root .track-site-shell .ws-popup .ws-primary{background:#202938;color:#fff;border-color:#202938}
#root .track-site-shell .ws-panel h2{font-size:18px!important;line-height:1.4!important}
#root .track-site-shell .ws-popup>header h2{font-size:20px!important}
#root .track-site-shell .track-logout{margin:0;background:transparent;color:#f2f5fa;border:1px solid #607089;border-radius:9px;min-width:44px;min-height:44px}
#root .track-site-shell .track-logout:hover{background:#374559;color:#fff}
.ws-popup{max-width:calc(100vw - 32px)}
.ws-composition meter::-webkit-meter-bar{background:#edf1f7;border:0;border-radius:8px}
.ws-composition meter::-webkit-meter-optimum-value{background:#4978d3;border-radius:8px}
.ws-composition meter::-moz-meter-bar{background:#4978d3;border-radius:8px}
@media(max-width:767px){.ws-popup{max-width:100vw}#root .track-site-shell .ws-tabs button{padding:9px 12px}}

content:
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
test('website analytics isolates approved toolbar/tab contrast and full-width mobile sheets from enquiry styles',()=>{
 const css=readFileSync(new URL('../src/WebsiteAnalytics.css',import.meta.url),'utf8');
 assert.match(css,/#root \.track-site-shell \.ws-page button\{[^}]*background:#fff;color:#293241/);
 assert.match(css,/#root \.track-site-shell \.ws-tabs button\[aria-selected=true\]\{background:#eaf0fb;color:#254b9c/);
 assert.match(css,/@media\(max-width:767px\)\{\.ws-popup\{max-width:100vw\}/);
 assert.match(css,/#root \.track-site-shell \.track-logout\{[^}]*background:transparent;color:#f2f5fa/);
});
